function defaultMeta(){return{version:GAME_VERSION,runs:0,totalDays:0,careerPoints:0,bestNetWorth:0,milestones:[],history:[],unlockedTraits:['benbi','tietkiem','kheomieng'],unlockedOrigins:['phuquoc','hagiang','cantho']};}
function loadMeta(){try{const d=defaultMeta(),x=Object.assign(d,JSON.parse(localStorage.getItem(META_KEY)||'{}'));x.unlockedTraits=x.unlockedTraits||d.unlockedTraits;x.unlockedOrigins=x.unlockedOrigins||d.unlockedOrigins;x.milestones=x.milestones||[];syncTraitUnlocks(x);syncOriginUnlocks(x);return x;}catch{return defaultMeta();}}
function saveMeta(){localStorage.setItem(META_KEY,JSON.stringify(meta));}
function persistNow(){try{save();saveMeta();}catch{}}
function normalizeEvent(ev){if(!ev)return null;if(!ev.eventId)ev.eventId=`ev_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;if(!Array.isArray(ev.choices))ev.choices=[];return ev;}
function queueEvent(ev,{front=false}={}){if(!state||!ev)return null;normalizeEvent(ev);if(front)state.events.unshift(ev);else state.events.push(ev);state.activeEventId=state.events[0]?.eventId||null;save();return ev;}
function loadSlot(i){try{return JSON.parse(localStorage.getItem(SLOT_KEY(i)));}catch{return null;}}
function save(){if(!state)return;state.updatedAt=Date.now();localStorage.setItem(SLOT_KEY(slot),JSON.stringify(state));}
function eraseSlot(i){localStorage.removeItem(SLOT_KEY(i));}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function clamp(v,a,b){return Math.max(a,Math.min(b,v));}
function rnd(a,b){return Math.floor(Math.random()*(b-a+1))+a;}
function pick(a){return a[Math.floor(Math.random()*a.length)];}
function fmt(v){const n=Math.abs(Math.round(v)),sign=v<0?'-':'';if(n>=1000000000)return sign+(n/1000000000).toLocaleString('vi-VN',{maximumFractionDigits:2})+' tỷ';if(n>=1000000)return sign+(n/1000000).toLocaleString('vi-VN',{maximumFractionDigits:1})+' tr';if(n>=1000)return sign+Math.round(n/1000).toLocaleString('vi-VN')+'k';return sign+n.toLocaleString('vi-VN')+'đ';}
function priceText(v){if(!v)return'Miễn phí';return fmt(v).replace(/k$/,'K').replace(/ tr$/,' triệu');}
function fmtDuration(m){m=Math.max(0,Math.round(m));const h=Math.floor(m/60),r=m%60;if(!h)return `${r} phút`;if(!r)return `${h} giờ`;return `${h}g ${r}p`;}
function timeLabel(m=state?.clock||DEFAULT_WAKE){const x=((Math.round(m)%1440)+1440)%1440;return `${String(Math.floor(x/60)).padStart(2,'0')}:${String(x%60).padStart(2,'0')}`;}
function trait(){return TRAITS.find(x=>x.id===state?.trait)||TRAITS[0];}
function origin(s=state){return ORIGINS.find(x=>x.id===(s?.originId||'hcm'))||ORIGINS.find(x=>x.id==='hcm')||ORIGINS[0];}
function location(s=state){return ORIGINS.find(x=>x.id===(s?.locationId||s?.originId||'hcm'))||origin(s);}
function provinceName(locId=state?.locationId){const map={phuquoc:'Kiên Giang',hagiang:'Hà Giang',cantho:'Cần Thơ',binhduong:'Bình Dương',hcm:'TP.HCM',dongnai:'Đồng Nai',danang:'Đà Nẵng',quangninh:'Quảng Ninh',nghean:'Nghệ An',hanoi:'Hà Nội'};return map[locId]||location({locationId:locId,originId:locId}).place;}
function localBusinessCatalog(){const maxLevel=Math.min(7,Math.max(2,careerStage()+1,wealthTier().id+1));return ALL_BUSINESSES.filter(b=>(!b.originIds||b.originIds.includes(state.locationId))&&b.level<=maxLevel);}
function allOwnedBusinessCatalog(){return ALL_BUSINESSES;}
function vehicle(){return VEHICLES.find(x=>x.id===state?.vehicle)||VEHICLES[0];}
function home(){return HOUSING.find(x=>x.id===state?.housing)||HOUSING[0];}
function partner(){return PARTNERS.find(x=>x.id===state?.relationship?.partnerId)||null;}
function businessCount(){return Object.values(state?.businesses||{}).reduce((a,b)=>a+b,0);}
function totalStaff(){let n=0;for(const b of ALL_BUSINESSES)n+=(state?.businesses?.[b.id]||0)*b.staff;return n;}
function furnitureItem(id){return FURNITURE.find(x=>x.id===id)||null;}
function ownedFurniture(category=null,s=state){const arr=Array.isArray(s?.furnitureOwned)?s.furnitureOwned:[];return category?arr.filter(x=>furnitureItem(x.itemId)?.category===category):arr;}
function soldFurniture(s=state){return Array.isArray(s?.furnitureSold)?s.furnitureSold:[];}
function bestFurniture(category,s=state){return ownedFurniture(category,s).map(x=>furnitureItem(x.itemId)).filter(Boolean).sort((a,b)=>(b.tier||0)-(a.tier||0))[0]||null;}
function furnitureResale(instance){const item=furnitureItem(instance?.itemId);if(!item)return 0;const age=Math.max(0,(state?.day||1)-(instance.boughtDay||state?.day||1)),ageFactor=Math.max(.72,1-age/1600);return Math.round((instance.boughtPrice||item.price)*(item.resale||.35)*ageFactor);}
function furnitureNetWorth(s=state){return ownedFurniture(null,s).reduce((sum,x)=>sum+furnitureResale(x),0);}
function homeAmenityTier(category){const own=bestFurniture(category)?.tier||0;let included=0;if(category==='bed')included=home().includedBed||0;if(category==='fridge')included=home().includedFridge||0;return Math.max(own,included);}
function hasUsableFridge(){return homeAmenityTier('fridge')>0&&!hasIssue('fridgeBroken');}
function furnitureBenefits(){const bedItem=bestFurniture('bed'),includedBed=home().includedBed||0,useOwnedBed=!!bedItem&&(bedItem.tier||0)>=includedBed,bedSleep=useOwnedBed?(bedItem.sleep||0):Math.round(includedBed*1.4),cool=bestFurniture('cooling')?.sleep||0,tv=bestFurniture('tv')?.mood||0,sofaItem=bestFurniture('sofa'),sofaMood=sofaItem?.mood||0,wash=bestFurniture('washing')?.monthlySave||0,sofa=sofaItem?.homeLove||0,dining=bestFurniture('dining')?.homeLove||0,pc=bestFurniture('computer')?.manage||0,fr=homeAmenityTier('fridge');const fridge=bestFurniture('fridge'),includedFridge=home().includedFridge||0,useOwnedFridge=!!fridge&&(fridge.tier||0)>=includedFridge;return{sleep:Math.max(0,Math.round(bedSleep+cool)),homeMood:tv+sofaMood,monthlySave:wash,homeLove:sofa+dining,manage:pc,fridgeTier:fr,fridgeCapacity:useOwnedFridge?(fridge.capacity||0):(includedFridge?8+includedFridge*2:0),freshDays:useOwnedFridge?(fridge.fresh||0):(includedFridge?3+includedFridge:0)};}
function netWorth(s=state){if(!s)return 0;let n=s.cash-(s.debt||0);const v=VEHICLES.find(x=>x.id===s.vehicle);if(v)n+=v.price*v.resale;const h=HOUSING.find(x=>x.id===s.housing);if(h?.kind==='buy')n+=h.price*.82;n+=furnitureNetWorth(s);for(const b of ALL_BUSINESSES)n+=(s.businesses?.[b.id]||0)*b.cost*.60;return Math.round(n);}
function wealthTier(s=state){const n=Math.max(0,netWorth(s));let out=WEALTH_TIERS[0];for(const t of WEALTH_TIERS)if(n>=t.min)out=t;return out;}
function socialStatusScore(s=state){if(!s)return 0;const v=VEHICLES.find(x=>x.id===s.vehicle)||VEHICLES[0],h=HOUSING.find(x=>x.id===s.housing)||HOUSING[0];const furn=ownedFurniture(null,s).reduce((sum,x)=>sum+(furnitureItem(x.itemId)?.prestige||0),0);return clamp(Math.round((s.reputation||0)*.28+(v.prestige||0)+(h.prestige||0)+Math.min(18,furn*.22)+(s.socialBonus||0)),0,100);}
function markActivity(kind,points=1){if(!state)return;state.dayActivityPoints=(state.dayActivityPoints||0)+points;state.dayActivities=state.dayActivities||{};state.dayActivities[kind]=(state.dayActivities[kind]||0)+1;}
function assetRequirementText(a){const r=[];if(a.minNet&&netWorth()<a.minNet)r.push(`tài sản ròng ${fmt(a.minNet)}`);if(a.minActive&&(state.stats.activeDays||0)<a.minActive)r.push(`${a.minActive} ngày hoạt động`);if(a.minStatus&&socialStatusScore()<a.minStatus)r.push(`vị thế ${a.minStatus}`);return r.join(' · ');}
function assetUnlocked(a){return (!a.minNet||netWorth()>=a.minNet)&&(!a.minActive||(state.stats.activeDays||0)>=a.minActive)&&(!a.minStatus||socialStatusScore()>=a.minStatus);}
function assetReserveMonths(a){return (a.tier>=8||a.quality>=6)?9:(a.tier>=6||a.quality>=5)?6:3;}
function assetReserveNeeded(a){return Math.round(monthlyExpenseEstimate()*assetReserveMonths(a));}
function livingMultiplier(){return (trait().mods.living||1)*(location()?.cost||1);}
function incomeMultiplier(job){let m=1;if(job.kind==='skilled')m*=trait().mods.skilled||1;if(job.kind==='risky')m*=trait().mods.risky||1;if(traitFitsJob(job))m*=1.08;return m;}
function weather(){return WEATHER.find(w=>w.id===state?.weather)||WEATHER[0];}
function changeCash(delta,label='Giao dịch',animate=true){if(!state||!Number.isFinite(delta)||!delta)return;const d=Math.round(delta);state.cash+=d;if(d>0)state.stats.earned+=d;else state.stats.spent+=Math.abs(d);const dl=ensureDayLedger();if(dl){if(d>0)dl.cashIn+=d;else dl.cashOut+=Math.abs(d);}if(animate)cashFxQueue.push({delta:d,label});}
function flushCashFx(){if(!cashFxQueue.length)return;const anchor=document.querySelector('[data-cash-anchor]');if(!anchor){cashFxQueue=[];return;}const r=anchor.getBoundingClientRect();cashFxQueue.splice(0,8).forEach((fx,i)=>setTimeout(()=>{const el=document.createElement('div');el.className=`money-fx ${fx.delta>0?'gain':'loss'}`;el.innerHTML=`${fx.delta>0?'+':'−'}${fmt(Math.abs(fx.delta))}<small>${esc(fx.label)}</small>`;el.style.left=`${Math.max(8,Math.min(window.innerWidth-180,r.left+r.width/2-60+(i%3-1)*18))}px`;el.style.top=`${Math.max(74,r.bottom+4)}px`;document.body.appendChild(el);setTimeout(()=>el.remove(),2550);},i*170));}
function log(text,type='normal'){if(!state)return;state.journal.unshift({day:state.day,date:dateLabel(),time:timeLabel(),text,type});state.journal=state.journal.slice(0,220);}
function news(title,text,type='Đời sống'){state.news.unshift({day:state.day,date:dateLabel(),time:timeLabel(),title,text,type});state.news=state.news.slice(0,40);}
function syncTraitUnlocks(m=meta){for(const t of TRAITS)if((m.careerPoints||0)>=t.unlock&&!m.unlockedTraits.includes(t.id))m.unlockedTraits.push(t.id);}
function syncOriginUnlocks(m=meta){m.unlockedOrigins=m.unlockedOrigins||[];for(const o of ORIGINS)if((m.careerPoints||0)>=o.unlock&&!m.unlockedOrigins.includes(o.id))m.unlockedOrigins.push(o.id);}
function careerPoint(key,label){if(meta.milestones.includes(key))return;meta.milestones.push(key);meta.careerPoints++;syncTraitUnlocks(meta);syncOriginUnlocks(meta);saveMeta();news('Điểm sự nghiệp',`${label}. Bạn nhận +1 Điểm sự nghiệp. Điểm này mở thêm cả tính cách lẫn xuất thân cho các cuộc đời sau.`,'Roguelite');}
function milestone(key,title,text){if(state.milestones.includes(key))return false;state.milestones.push(key);state.storyFlags[key]=true;news(title,text,'Cột mốc');log(`${title}: ${text}`,'good');careerPoint(key,title);return true;}

function isoToday(){const d=new Date(),y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`;}
function parseISO(iso){const [y,m,d]=String(iso||isoToday()).split('-').map(Number);return new Date(Date.UTC(y,m-1,d));}
function isoFromDate(d){return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;}
function addDaysISO(iso,days){const d=parseISO(iso);d.setUTCDate(d.getUTCDate()+days);return isoFromDate(d);}
function addYearsISO(iso,years){const d=parseISO(iso),m=d.getUTCMonth(),day=d.getUTCDate();d.setUTCFullYear(d.getUTCFullYear()+years);if(d.getUTCMonth()!==m){d.setUTCMonth(m+1,0);}return isoFromDate(d);}
function compareISO(a,b){return String(a).localeCompare(String(b));}
function isLeapYear(y){return y%4===0&&(y%100!==0||y%400===0);}
function calendarInfo(s=state){const d=parseISO(s?.calendarDate||isoToday()),dow=d.getUTCDay();return{iso:isoFromDate(d),year:d.getUTCFullYear(),month:d.getUTCMonth()+1,day:d.getUTCDate(),weekday:['Chủ Nhật','Thứ Hai','Thứ Ba','Thứ Tư','Thứ Năm','Thứ Sáu','Thứ Bảy'][dow],leap:isLeapYear(d.getUTCFullYear())};}
function dateLabel(s=state){const c=calendarInfo(s);return `${String(c.day).padStart(2,'0')}/${String(c.month).padStart(2,'0')}/${c.year}`;}
function monthKey(s=state){const c=calendarInfo(s);return `${c.year}-${String(c.month).padStart(2,'0')}`;}
function weekday(){return calendarInfo().weekday;}
function playerAge(s=state){if(!s)return STARTING_PLAYER_AGE;const birth=s.birthDate||addYearsISO(s.runStartDate||s.calendarDate||isoToday(),-STARTING_PLAYER_AGE),now=parseISO(s.calendarDate||isoToday()),b=parseISO(birth);let age=now.getUTCFullYear()-b.getUTCFullYear();if(now.getUTCMonth()<b.getUTCMonth()||(now.getUTCMonth()===b.getUTCMonth()&&now.getUTCDate()<b.getUTCDate()))age--;return Math.max(STARTING_PLAYER_AGE,age);}
function nextBirthdayISO(s=state){if(!s)return null;const b=parseISO(s.birthDate||addYearsISO(s.runStartDate||s.calendarDate||isoToday(),-STARTING_PLAYER_AGE)),now=parseISO(s.calendarDate||isoToday());let y=now.getUTCFullYear();let candidate=addYearsISO(isoFromDate(b),y-b.getUTCFullYear());if(compareISO(candidate,s.calendarDate)<=0)candidate=addYearsISO(isoFromDate(b),y-b.getUTCFullYear()+1);return candidate;}
function childAge(c){if(c?.birthDate){const a=parseISO(c.birthDate),b=parseISO(state.calendarDate);let y=b.getUTCFullYear()-a.getUTCFullYear();if(b.getUTCMonth()<a.getUTCMonth()||(b.getUTCMonth()===a.getUTCMonth()&&b.getUTCDate()<a.getUTCDate()))y--;return Math.max(0,y);}return Math.max(0,Math.floor((state.day-(c?.birthDay||state.day))/365.2425));}
function regionProgress(locId=state?.locationId){if(!state)return{jobs:0,days:0,activeDays:0,rep:0,maxStage:0};state.regionProgress=state.regionProgress||{};const id=locId||state.locationId;if(!state.regionProgress[id])state.regionProgress[id]={jobs:0,days:0,activeDays:0,rep:id===state.locationId?(state.localReputation||0):0,maxStage:0};return state.regionProgress[id];}
function localCareerScore(locId=state?.locationId){const p=regionProgress(locId);return Math.round((p.jobs||0)*2+(p.rep||0)+(p.activeDays||0)*.35);}
function careerStage(locId=state?.locationId){const score=localCareerScore(locId);let stage=0;for(const x of CAREER_STAGES)if(score>=x.score)stage=x.id;const p=regionProgress(locId);p.maxStage=Math.max(p.maxStage||0,stage);return stage;}
function careerStageInfo(locId=state?.locationId){return CAREER_STAGES[careerStage(locId)]||CAREER_STAGES[0];}
function statusTone(v,inverse=false){const x=clamp(Number(v)||0,0,100),score=inverse?100-x:x;return score>=70?'good':score>=45?'watch':score>=25?'low':'critical';}
function sleepDebtPct(){return clamp(Math.round((state?.sleepDebt||0)/480*100),0,100);}
function foodUnlocked(f){if((f.tier||0)>careerStage())return false;if(f.minNet&&netWorth()<f.minNet)return false;if(f.minRep&&state.reputation<f.minRep)return false;if(f.locations?.length&&!f.locations.includes(state.locationId))return false;if(f.relationship?.length&&!f.relationship.includes(state.relationship.status))return false;return true;}
function stableRank(text){let h=2166136261;for(const ch of String(text)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;}
function phoneProfile(seedText=''){const seed=stableRank(`${seedText}_${state?.runStartDate||isoToday()}`),carrier=PHONE_CARRIERS[seed%PHONE_CARRIERS.length],prefix=carrier.prefixes[(seed>>>4)%carrier.prefixes.length],suffix=String(1000+((seed>>>8)%9000));return{carrier:carrier.name,number:`${prefix} ••• ${suffix}`,messages:[],privateOffers:[],lastOfferDay:0};}
function ensurePhone(){if(!state.phone)state.phone=phoneProfile(state.name||'player');state.phone.messages=Array.isArray(state.phone.messages)?state.phone.messages:[];state.phone.privateOffers=Array.isArray(state.phone.privateOffers)?state.phone.privateOffers:[];state.phone.lastOfferDay=state.phone.lastOfferDay||0;return state.phone;}
function pushPhoneMessage(sender,text,type='Đời sống',{offerId=null,unread=true}={}){const ph=ensurePhone();ph.messages.unshift({id:`sms_${Date.now()}_${Math.random().toString(36).slice(2,6)}`,day:state.day,date:state.calendarDate,time:timeLabel(),sender,text,type,offerId,unread});ph.messages=ph.messages.slice(0,60);save();}
function unreadPhoneCount(){return ensurePhone().messages.filter(x=>x.unread).length;}
function markPhoneRead(){for(const m of ensurePhone().messages)m.unread=false;save();renderGame();}
function activePrivateOffers(){return ensurePhone().privateOffers.filter(o=>o.status==='new'&&o.locationId===state.locationId&&o.expiresDay>=state.day);}
function privateSenderForJob(j){const local={phuquoc:['Cô Năm quán ăn','Anh Hải ở bến','Chị Nhi khách sạn'],hagiang:['Chị Hà homestay','Anh Duy dẫn tour','Cô Mỷ chợ phiên'],cantho:['Chú Sáu vựa trái cây','Chị Thảo cửa hàng','Anh Phúc mối hàng'],binhduong:['Anh Tân xưởng nhỏ','Chị Hương nhân sự','Chú Bảy kho'],hcm:['Anh Khoa sales','Chị Vy shop online','Cô Lan quán ăn'],dongnai:['Anh Nam mối vườn','Chị Hân vật tư','Chú Tư nhà vườn'],danang:['Chị My điều hành tour','Anh Minh nhà hàng','Cô Hương quán biển'],quangninh:['Chị Trang điều phối cảng','Anh Quân dịch vụ vịnh','Chú Hòa kho'],nghean:['Anh Đức xe tuyến','Chị An cửa hàng','Cô Oanh đặc sản'],hanoi:['Chị Linh văn phòng','Anh Khánh B2B','Cô Hà cửa hàng']};return pick(local[state.locationId]||['Người quen']);}
function generateDailyPrivateOffer(force=false){if(!state)return false;const ph=ensurePhone();if(ph.lastOfferDay===state.day)return false;ph.lastOfferDay=state.day;ph.privateOffers=ph.privateOffers.filter(o=>o.expiresDay>=state.day-1&&o.status!=='expired');const chance=.16+(trait().id==='quanHe'?.16:0)+Math.min(.12,(state.localReputation||0)/180)+(state.stats.jobsDone>2?.06:0);if(!force&&Math.random()>chance)return false;let pool=eligibleJobs().filter(j=>!j.capital&&jobLocationOK(j)&&findJobSchedule(j));const known=pool.filter(j=>(state.jobHistory?.[j.id]||0)>0);if(known.length)pool=known;if(!pool.length)return false;const j=pick(pool),premium=rnd(110,124)/100,sender=privateSenderForJob(j),offer={id:`po_${Date.now()}_${Math.random().toString(36).slice(2,6)}`,jobId:j.id,locationId:state.locationId,createdDay:state.day,expiresDay:state.day,premium,status:'new',sender};ph.privateOffers.unshift(offer);ph.privateOffers=ph.privateOffers.slice(0,18);pushPhoneMessage(sender,`Có mối “${j.name}”. Không đăng ra chợ việc; nếu nhận hôm nay tôi trả nhỉnh hơn khoảng ${Math.round((premium-1)*100)}%. Sang tab Việc làm để xem lịch có ghép được không.`,'Mối việc',{offerId:offer.id});return true;}
function pendingJobClaims(){return (state?.commitments||[]).filter(c=>c.status==='awaiting_claim');}
function jobSettlementPreview(c,j,mult=1){const o=c.outcome||{},direct=o.direct||0;if(j.capital){const held=c.capitalHeld||j.capital||0,profit=Math.round((o.profit||0)*mult)-direct;return{net:profit,payout:Math.max(0,held+profit),gross:o.gross||0,direct,capitalHeld:held};}const net=Math.round((o.gross||0)*mult)-direct;return{net,payout:net,gross:Math.round((o.gross||0)*mult),direct,capitalHeld:0};}
function claimJobReward(id){const c=pendingJobClaims().find(x=>x.id===id),j=c&&jobById(c.jobId);if(!c||!j)return;const r=c.result||jobSettlementPreview(c,j,c.resultMultiplier||1),client=c.client||clientProfileForJob(j,c.source||'public'),pay=c.payment||paymentTermForJob(j,c.source||'public',client);c.client=client;c.payment=pay;let rec=null;if(pay.mode==='now'){if(j.capital){state.cash+=r.payout;if(r.net>0)state.stats.earned+=r.net;else state.stats.spent+=Math.abs(r.net);const dl=ensureDayLedger();if(dl){dl.cashIn+=Math.max(0,r.payout);dl.jobCashNet+=r.net;}cashFxQueue.push({delta:r.payout,label:`Thu tiền & hoàn vốn · ${j.name}`});}else{changeCash(r.net,j.name);const dl=ensureDayLedger();if(dl)dl.jobCashNet+=r.net;}}else rec=createReceivable(c,j,r);const repGain=c.repGain||0;state.reputation+=repGain;if(j.locationIds?.includes(c.locationId)){const rp=regionProgress(c.locationId);rp.jobs=(rp.jobs||0)+1;rp.rep=(rp.rep||0)+repGain;if(c.locationId===state.locationId)state.localReputation=rp.rep;}const group=jobSkillGroup(j);state.jobSkills[group]=(state.jobSkills[group]||0)+1;state.jobHistory[j.id]=(state.jobHistory[j.id]||0)+1;state.stats.jobsDone++;c.status='claimed';c.claimedAtMs=Date.now();c.claimedNet=r.net;c.receivableId=rec?.id||null;updateStandingContract(c,true);if(state.jobHistory[j.id]===3)news('Khách bắt đầu nhớ mặt bạn',`Bạn đã hoàn thành “${j.name}” 3 lần. Từ đây mối quen này có xu hướng xuất hiện thường hơn và bạn đọc khoảng tiền chính xác hơn.`,'Quan hệ nghề');maybeOfferStandingContract(j);if(rec){news('Đã nghiệm thu — tiền chưa vào túi',`${client.name} xác nhận ${fmt(rec.cashAmount)} sẽ thanh toán theo điều khoản “${pay.label}”. Đây là khoản phải thu, chưa phải tiền mặt để tiêu.`,'Dòng tiền');log(`Chốt “${j.name}”: lãi/thu nhập ${r.net>=0?'+':''}${fmt(r.net)} nhưng tiền theo ${pay.label.toLowerCase()}.`,'good');}else log(`Tự tay nhận kết quả “${j.name}”: ${r.net>=0?'+':''}${fmt(r.net)}${j.capital?` · dòng tiền về ${fmt(r.payout)} gồm vốn quay lại`:''}.`,'good');checkMilestones();checkStoryBeats();checkEndingReadiness();save();renderGame();setTimeout(flushCashFx,60);}
function pendingClaimsPanel(){const list=pendingJobClaims();if(!list.length)return'';return `<div class="claim-panel"><div class="row between"><div><b>💰 Công việc đã xong — chờ bạn chốt thành quả</b><div class="mini muted">Mối trả ngay sẽ vào Tiền mặt; mối trả cuối ngày/công nợ sẽ chuyển thành khoản đang chờ về.</div></div><span class="nav-badge alert">!</span></div><div class="planner-list">${list.map(c=>{const j=jobById(c.jobId),r=c.result||jobSettlementPreview(c,j,c.resultMultiplier||1),client=c.client||clientProfileForJob(j,c.source||'public'),pay=c.payment||paymentTermForJob(j,c.source||'public',client),cashAmt=j?.capital?r.payout:r.net;return `<div class="claim-row"><div><strong>${esc(j?.name||'Công việc')} · ${esc(client.name)}</strong><span class="mini muted">${areaName(c.targetArea,c.locationId)} · ${fmtDuration(c.duration)} · doanh thu ${fmt(r.gross)} · chi phí ${fmt(r.direct)} · tin cậy ${client.reliability}%</span><span class="tag ${paymentTone(pay.mode)}">${pay.label}</span><span class="claim-net ${r.net>=0?'up':'down'}">${pay.mode==='now'?'Nhận':pay.mode==='eod'?'Chờ cuối ngày':'Ghi công nợ'} ${fmt(cashAmt)}</span></div><button class="btn primary claim-btn" data-claim-job="${c.id}">${pay.mode==='now'?'Nhận tiền':'Xác nhận nghiệm thu'}</button></div>`;}).join('')}</div></div>`;}
function jobNegotiation(j){const n=state.jobNegotiations?.[j.id];return n&&n.day===state.day?n:null;}
function jobNegotiationMultiplier(j){return jobNegotiation(j)?.multiplier||1;}
function negotiateJob(id){if(isWorking())return toast('Đang làm việc; chưa thể gọi thương lượng một mối khác.');const j=jobById(id);if(!j||j.capital)return toast('Mối này không phù hợp để thương lượng công ngay lúc này.');if(jobNegotiation(j))return toast('Bạn đã thương lượng mối này hôm nay.');if(pendingJobClaims().length)return toast('Nhận kết quả việc vừa xong trước đã.');const skill=skillLevel(jobSkillGroup(j)).n,chance=clamp(.34+(trait().id==='kheomieng'?.20:0)+Math.min(.18,(state.localReputation||0)/120)+skill*.045,.25,.82),ok=Math.random()<chance;state.jobNegotiations=state.jobNegotiations||{};advanceClock(10,{awake:true,source:'Gọi thương lượng việc'});if(ok){const mult=rnd(106,115)/100;state.jobNegotiations[j.id]={day:state.day,status:'success',multiplier:mult};news('Thương lượng được giá tốt hơn',`Mối “${j.name}” đồng ý tăng khoảng ${Math.round((mult-1)*100)}% tiền công nếu bạn giữ đúng lịch.`,'Việc làm');}else{const lost=Math.random()<.32;state.jobNegotiations[j.id]={day:state.day,status:lost?'lost':'failed',multiplier:1};if(lost){state.jobOffers=state.jobOffers.filter(x=>x!==j.id);news('Mối đã thuê người khác',`Bạn thử đòi mức cao hơn cho “${j.name}”, nhưng họ cần chốt nhanh và đã giao việc cho người khác.`,'Việc làm');}else news('Không thương lượng thêm được',`Mối “${j.name}” giữ nguyên mức dự kiến. Bạn vẫn có thể nhận nếu lịch còn phù hợp.`,'Việc làm');}save();renderGame();}
function acceptPrivateOffer(id){if(isWorking())return toast('Bạn đang làm việc; có thể xem mối nhưng chưa nhận thêm lúc này.');const o=activePrivateOffers().find(x=>x.id===id),j=o&&jobById(o.jobId);if(!o||!j)return toast('Mối riêng này đã hết hạn hoặc không còn ở địa phương hiện tại.');if(pendingJobClaims().length)return toast('Hãy nhận kết quả công việc vừa xong trước khi nhận mối mới.');const plan=findJobSchedule(j);if(!plan)return toast('Không còn khe giờ phù hợp cho mối riêng này.');const energy=Math.ceil(j.energy*(trait().mods.energy||1));if(state.energy<energy)return toast('Năng lượng hiện tại quá thấp.');const client=clientProfileForJob(j,'sms',o.sender),payment=paymentTermForJob(j,'sms',client),outcome=frozenJobOutcome(j,plan),pMult=o.premium*paymentPremium(payment);outcome.gross=Math.round(outcome.gross*pMult);outcome.profit=Math.round(outcome.profit*pMult);const c={id:`job_${Date.now()}_${Math.random().toString(36).slice(2,6)}`,jobId:j.id,locationId:state.locationId,day:state.day,date:state.calendarDate,status:'accepted',acceptedAtClock:state.clock,start:plan.start,end:plan.end,duration:plan.duration,travel:plan.travel,sourceArea:plan.sourceArea,targetArea:plan.targetArea,outcome,micro:generateJobMicro(j),createdAtMs:Date.now(),source:'sms',privateOfferId:o.id,client,payment,paymentPremiumApplied:true};state.commitments.push(c);o.status='accepted';for(const m of ensurePhone().messages)if(m.offerId===o.id)m.unread=false;log(`Nhận mối riêng từ ${o.sender}: “${j.name}” · lịch ${timeLabel(c.start)}–${timeLabel(c.end)}.`);save();renderGame();}
function jobSourceText(j){const hist=state.jobHistory?.[j.id]||0;return hist>=3?'Khách cũ / chợ công khai':'Chợ việc công khai';}
function jobQualityText(j){const hist=state.jobHistory?.[j.id]||0;if(j.capital)return'Vốn & biên lợi nhuận';if(hist>=3)return'Có khả năng thành mối dài';if((j.stage||0)>=3)return'Cơ hội nâng tầm nghề';if(['delivery','labor'].includes(jobSkillGroup(j)))return'Tiền công tương đối chắc';return'Học nghề & xây quan hệ';}
function jobRequirementText(j){const a=[];if((j.vehicle||0)>0)a.push(`phương tiện cấp ${j.vehicle}+`);if((j.minRep||0)>0)a.push(`uy tín địa phương ${j.minRep}+`);if(j.capital)a.push(`vốn xoay ${fmt(j.capital)}`);if((j.stage||0)>0)a.push(`tầng nghề ${j.stage+1}`);return a.length?a.join(' · '):'không yêu cầu nền tảng đặc biệt';}
function tabBadge(id){if(id==='doisong'&&state.activeLifeAction)return{txt:'•',kind:'info'};if(id==='vieclam'){if(pendingJobClaims().length)return{txt:'!',kind:'alert'};if(dueReceivables().length)return{txt:String(dueReceivables().length),kind:'alert'};if(activePrivateOffers().length)return{txt:String(activePrivateOffers().length),kind:'info'};const soon=activeCommitments().some(c=>c.start-state.clock<=45&&c.start>=state.clock);if(soon)return{txt:'•',kind:'warn'};}if(id==='nha'&&activeIssues().length)return{txt:'!',kind:'alert'};if(id==='tinhcam'&&activePersonalCommitments().some(c=>c.start-state.clock<=60&&c.start>=state.clock))return{txt:'!',kind:'alert'};if(id==='sunghiep'&&state.endingReady)return{txt:'!',kind:'info'};return null;}
function navTabHtml(id,label){const b=tabBadge(id);return `${label}${b?`<span class="nav-badge ${b.kind}">${b.txt}</span>`:''}`;}
function overviewNewsItems(){const m=ensureMarket(),best=m.signals.slice().sort((a,b)=>Math.abs(b.pct)-Math.abs(a.pct))[0],seed=stableRank(`${state.calendarDate}_${state.locationId}_brief`),traffic=['đường vào trung tâm đông hơn bình thường','giao thông khá thoáng','khu chợ đông từ sớm','một số tuyến đang chậm vì giờ cao điểm'][seed%4],local=[{icon:weather().icon,title:`Thời tiết ${location().place}`,text:weather().desc},{icon:'📍',title:'Nhịp khu vực',text:`${traffic}. Bạn đang ở ${areaName(state.currentArea)}.`},{icon:best.pct>=0?'📈':'📉',title:best.name,text:`Tín hiệu hôm nay đang ${best.pct>=0?'thuận hơn':'yếu hơn'} ngày thường khoảng ${Math.abs(best.pct)}%. Muốn biến tin này thành tiền phải sang Việc làm và chọn đúng nghề.`}];if(activeIssues().length)local.push({icon:'🔧',title:'Việc nhà còn tồn',text:`Có ${activeIssues().length} vấn đề chưa xử lý; tab Nhà đang có cảnh báo.`});const status=socialStatusScore(),high=[];if(status>=28||wealthTier().id>=4){const d=((seed>>5)%9)-4;high.push({icon:'🇻🇳',title:'Kinh tế trong nước · mô phỏng',text:`Nhu cầu tiêu dùng/doanh nghiệp đang ${d>=0?'nhích lên':'chậm lại'} khoảng ${Math.abs(d)}% theo chỉ báo game. Nội dung này là dữ liệu mô phỏng, không phải tin thật.`});}if(status>=58||wealthTier().id>=6){const d=((seed>>9)%11)-5;high.push({icon:'🌐',title:'Quốc tế · mô phỏng',text:`Nhiên liệu, du lịch và thương mại quốc tế đang tạo mức ảnh hưởng ${d>=0?'+':''}${d}% lên một số ngành cấp cao trong thế giới game.`});}return{local,high};}
function overviewNewsPanel(){const b=overviewNewsItems();return `<div class="card"><div class="screen-title"><div><h2>Bản tin quanh bạn</h2><div class="mini muted">Tổng quan chỉ để đọc tình hình. Muốn nhận/xếp việc, hãy sang tab <b>Việc làm</b>.</div></div><span class="tag">Bản tin trong hành trình</span></div><div class="news-grid">${b.local.map(x=>`<div class="news-tile"><span>${x.icon}</span><div><b>${esc(x.title)}</b><p>${esc(x.text)}</p></div></div>`).join('')}</div>${b.high.length?`<h3 style="margin-top:12px">Tin mở theo vị thế</h3><div class="news-grid">${b.high.map(x=>`<div class="news-tile high"><span>${x.icon}</span><div><b>${esc(x.title)}</b><p>${esc(x.text)}</p></div></div>`).join('')}</div>`:`<div class="mini muted locked-news">🔒 Khi Vị thế/tài sản tăng, Tổng quan sẽ mở thêm bản tin kinh tế trong nước và thế giới mô phỏng.</div>`}</div>`;}
function furnitureBenefitText(it){if(!it)return'Không có dữ liệu lợi ích.';const out=[];if(it.sleep)out.push(`Ngủ/hồi phục +${it.sleep}`);if(it.capacity)out.push(`Kho lạnh ${it.capacity} phần`);if(it.fresh)out.push(`Giữ tươi ~${it.fresh} ngày`);if(it.mood)out.push(`Tinh thần tại nhà +${it.mood}`);if(it.monthlySave)out.push(`Giảm ~${fmt(it.monthlySave)}/tháng chi phí lặt vặt`);if(it.homeLove)out.push(`Hoạt động ở nhà/tình cảm +${it.homeLove}`);if(it.manage)out.push(`Hỗ trợ quản trị +${Math.round(it.manage*1000)/10}%`);if(it.prestige)out.push(`Vị thế +${it.prestige}`);if(!out.length)out.push('Tiện nghi cơ bản, chủ yếu nâng chất lượng sống');return out.join(' · ');}
function freshDayLedger(date=state?.calendarDate||isoToday(),cash=state?.cash||0){return{date,startCash:Math.round(cash),cashIn:0,cashOut:0,jobCashNet:0,creditCreated:0,receivableCollected:0,workMinutes:0,travelMinutes:0,fitnessMinutes:0,mealCount:0,jobsCompleted:0,missedCommitments:0,missedOffers:0};}
function ensureDayLedger(){if(!state)return null;if(!state.dayLedger||state.dayLedger.date!==state.calendarDate)state.dayLedger=freshDayLedger(state.calendarDate,state.cash);return state.dayLedger;}
function clientProfileForJob(j,source='public',forcedName=''){const loc=state?.locationId||'hcm',pool=REGION_CLIENTS[loc]||REGION_CLIENTS.hcm,key=`${loc}_${j?.id||'job'}_${source}`,h=stableRank(key),name=forcedName||pool[h%pool.length],bonus=source==='sms'?6:source==='contract'?8:0,reliability=clamp(64+(h%31)+bonus,62,99);return{name,reliability,key};}
function paymentTermForJob(j,source='public',client=null){const c=client||clientProfileForJob(j,source),h=stableRank(`${c.key}_${j?.id||''}_pay`),stage=j?.stage||0,roll=(h>>5)%100;if(source==='sms'){if(roll<82)return{mode:'now',label:'Trả ngay khi nghiệm thu',dueDays:0};if(roll<97)return{mode:'eod',label:'Chuyển cuối ngày',dueDays:0};return{mode:'credit',label:'Công nợ 3 ngày',dueDays:3};}if(source==='contract'){if(roll<35)return{mode:'now',label:'Trả ngay khi nghiệm thu',dueDays:0};if(roll<68)return{mode:'eod',label:'Chuyển cuối ngày',dueDays:0};const days=[3,5,7][h%3];return{mode:'credit',label:`Công nợ ${days} ngày`,dueDays:days};}if(stage<=1&&!j?.capital){if(roll<70)return{mode:'now',label:'Trả ngay khi nghiệm thu',dueDays:0};if(roll<95)return{mode:'eod',label:'Chuyển cuối ngày',dueDays:0};return{mode:'credit',label:'Công nợ 3 ngày',dueDays:3};}if(stage<=3&&!j?.capital){if(roll<55)return{mode:'now',label:'Trả ngay khi nghiệm thu',dueDays:0};if(roll<82)return{mode:'eod',label:'Chuyển cuối ngày',dueDays:0};const days=[3,5][h%2];return{mode:'credit',label:`Công nợ ${days} ngày`,dueDays:days};}if(roll<40)return{mode:'now',label:'Trả ngay khi nghiệm thu',dueDays:0};if(roll<70)return{mode:'eod',label:'Chuyển cuối ngày',dueDays:0};const days=[3,5,7][h%3];return{mode:'credit',label:`Công nợ ${days} ngày`,dueDays:days};}
function paymentPremium(pay){if(!pay)return 1;if(pay.mode==='eod')return 1.06;if(pay.mode==='credit')return pay.dueDays>=7?1.20:pay.dueDays>=5?1.16:1.12;return 1;}
function paymentTone(mode){return mode==='now'?'good':mode==='eod'?'warn':'credit';}
function receivableDue(r){if(!r||r.status!=='pending')return false;if(state.day>r.dueDay)return true;if(state.day<r.dueDay)return false;return state.clock>=(r.dueClock??0);}
function pendingReceivables(){return (state?.receivables||[]).filter(r=>r.status==='pending');}
function dueReceivables(){return pendingReceivables().filter(receivableDue);}
