function foodCatalogToday(){const unlocked=FOODS.filter(foodUnlocked),loc=state.locationId,date=state.calendarDate,stage=careerStage(),out=[];const ranked=arr=>arr.slice().sort((a,b)=>stableRank(`${date}_${loc}_${a.id}`)-stableRank(`${date}_${loc}_${b.id}`));const add=(arr,n)=>{for(const f of ranked(arr)){if(out.some(x=>x.id===f.id))continue;out.push(f);if(--n<=0)break;}};add(unlocked.filter(f=>f.locations?.includes(loc)),2);add(unlocked.filter(f=>(f.tier||0)>=Math.max(0,stage-1)&&(f.tier||0)<=stage),3);add(unlocked.filter(f=>(f.tier||0)<=1),2);add(unlocked.filter(f=>(f.tier||0)>=2||f.relationship?.length),2);add(unlocked,8-out.length);return out.slice(0,8).sort((a,b)=>(a.tier||0)-(b.tier||0));}
