function maybeRegionalMoneyEvent(){if(!state||state.events.length)return false;const last=state.storyFlags.lastRegionalMoneyDay||-99;if(state.day-last<4||Math.random()>.24)return false;const stage=careerStage(),history=state.regionalEventHistory||[];let pool=REGIONAL_MONEY_EVENTS.filter(e=>e.locationId===state.locationId&&e.stage<=stage&&!history.slice(-8).includes(e.id));if(!pool.length)pool=REGIONAL_MONEY_EVENTS.filter(e=>e.locationId===state.locationId&&e.stage<=stage);if(!pool.length)return false;const fit=pool.filter(e=>e.affinity?.includes(trait().id)),src=(fit.length&&Math.random()<.58)?fit:pool,raw=pick(src),matched=raw.affinity?.includes(trait().id);const ev={title:raw.title,text:`${raw.text}${matched?` Lối sống “${trait().name}” giúp bạn nhìn thấy thêm lợi thế trong tình huống này.`:''}`,type:'Cơ hội địa phương',locationId:state.locationId,choices:raw.choices.map(c=>{const x=JSON.parse(JSON.stringify(c));if(matched&&x.gain)x.gain=Math.round(x.gain*1.10);if(matched){x.effect=x.effect||{};x.effect.localRep=(x.effect.localRep||0)+1;}return x;})};queueEvent(ev);state.storyFlags.lastRegionalMoneyDay=state.day;state.regionalEventHistory=[...history,raw.id].slice(-20);return true;}
